    <script type="module">
        /* 更新进度条辅助函数 */
        function updateProgressBar(barId, valueId, rawValue, min = 0, max = 100, color = '#c8892f') {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;

                $(`#${valueId}`).text(clampedValue);
                $(`#${barId}`).css({
                    width: `${percentage}%`
                });
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>无法加载状态数据</div>");
                    return;
                }

                /* 世界状态 */
                $('#current-date').text(_.get(characterData, '世界时间.日期', 'N/A'));
                $('#current-time').text(_.get(characterData, '世界时间.时间', 'N/A'));
                $('#current-location').text(_.get(characterData, '当前地点', 'N/A'));

                /* 爱丽丝：好感度与关系 */
                updateProgressBar(
                    'affection-bar',
                    'affection-value',
                    _.get(characterData, '爱丽丝.好感度', 0),
                    0, 100, '#c8892f'
                );
                $('#relationship-badge').text(_.get(characterData, '爱丽丝.关系', 'N/A'));

                /* 案件追踪（不展示事件真相，避免剧透） */
                const caseName = _.get(characterData, '案件追踪.调查事件名称', '');
                const caseBrief = _.get(characterData, '案件追踪.调查事件简述', '');
                if (caseName) {
                    $('#case-name').text(caseName);
                    $('#case-brief').text(caseBrief || '暂无进一步记录');
                    $('#case-block').show();
                    $('#case-empty').hide();
                } else {
                    $('#case-block').hide();
                    $('#case-empty').show();
                }
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
            }
        }

        /* 初始化 */
        async function init() {
            await waitGlobalInitialized('Mvu');
            populateCharacterData();
        }

        $(errorCatched(init));
    </script>
